      SUBROUTINE SEXGETCC     FETCHES VALUES OF PARAMETERS FOR A SEXTUPOLECC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'XRAN.CIN'C      REAL            DATAR      EXTERNAL        DATAR, IDATACC     MAGNET LENGTHC      IADR = I + 1      L = DATAR(IADR)      IF (PRAN18(1) .NE. 0.0) L = L + PRAN18(1)*XRAN(1)      L = L*UNITI(8)      LMAG = LCC     INDICES OF OTHER PARAMETERSC      IB = IPTOJ(2)      IAP = IPTOJ(3)      IK2 = IPTOJ(4)C      IF (IK2 .NE. 0) GO TO 20      IF (IB .NE. 0) GO TO 5      B = 0.0      K2 = 0.0      AP = 0.0      GO TO 40CC     MAGNETIC FIELD AND APERTUREC    5 IADR = I + IB      B = DATAR(IADR)      IF (PRAN18(2) .NE. 0.0) B = B + PRAN18(2)*XRAN(2)      B = B*UNITI(9)*RI/PREF      IF (IAP .NE. 0) THEN        IADR = I + IAP        AP = DATAR(IADR)      ELSE        WRITE (NOUT,9007) 9007   FORMAT (' *** ERROR *** SEXTUPOLE APERTURE NOT GIVEN')        FLUSHL = .TRUE.        K2 = 0.0        AP = 0.0        GO TO 40      ENDIF      IF (AP .NE. 0.0) THEN        IF (PRAN18(3) .NE. 0.0)     1      AP = AP + PRAN18(3)*XRAN(3)        AP = AP*UNITI(1)        K2 = B/(RI*AP**2)      ELSE        WRITE (NOUT,9006) 9006   FORMAT (' *** ERROR *** SEXTUPOLE APERTURE SET TO ZERO')        FLUSHL = .TRUE.        K2 = 0.0      ENDIF      GO TO 40CC     NORMALIZED FIELD SECOND DERIVATIVEC   20 IADR = I + IK2      K2 = DATAR(IADR)      IF (PRAN18(4) .NE. 0.0)     1    K2 = K2 + PRAN18(4)*XRAN(4)      IF (MPMAD) K2 = 0.5*K2      K2 = K2/UNITI(8)**3C   40 IT = IPTOJ(6)      IF (IT .EQ. 0) THEN        NUMTYP = IT      ELSE        NUMTYP = IDATA(I + IT)      ENDIF      RETURN      END